using MiniCompiler.IR; using SemanticContracts; using SemanticQueries.Core; namespace Packages.BoundsOptimizer; public sealed class BoundsCheckOptimizer{private static readonly InBoundsQuery Q=new();public BoundsCheck Run(BoundsCheck check,SemanticSession s){var r=s.Query(Q,new(check.Array,check.Index,check.Point));return r.Status==QueryStatus.Known&&r.Value!.Proven?check with{Removed=true}:check;}}